  den.aspects.shared-base = {
    os =
      { pkgs, ... }:
      {
        environment.systemPackages = [ pkgs.hello ];
        # ...everything identical on both platforms...
      };
    # plain attrset form works too:
    # os.networking.hostName = "foo";
  };

  # Each host just picks it up:
